const input      = $('Extract Input').first().json;
const customers  = $('Query Customer Data').all().map(i => i.json);
const knowledge  = (() => { try { return $('Search Knowledge Base').all().map(i => i.json); } catch(e) { return []; } })();

const message    = input.message    || '';
const session_id = input.session_id || 'session-' + Date.now();
const topic      = input.topic      || 'retention';

const total     = customers.length;
const revenue   = customers.reduce((s, c) => s + (parseFloat(c.amount_spent) || 0), 0);
const rebooked  = customers.filter(c => c.rebooked === true || c.rebooked === 'true').length;
const followUps = total - rebooked;
const atRiskRev = customers.filter(c => !c.rebooked).reduce((s, c) => s + (parseFloat(c.amount_spent) || 0), 0);

const topCustomers = customers.slice(0, 10)
  .map(c => `  - ${c.name}: ${c.treatment} ($${c.amount_spent}), Provider: ${c.provider}, Last visit: ${c.last_visit}, Rebooked: ${c.rebooked ? 'Yes' : 'No'}`)
  .join('\n');

const customerContext = total > 0
  ? `PRACTICE CRM DATA (${total} active patients):
• Total Revenue: $${revenue.toLocaleString()} | Rebooking Rate: ${((rebooked/total)*100).toFixed(1)}% | Follow-ups Due: ${followUps} ($${atRiskRev.toLocaleString()} at-risk)
• Patient Sample:
${topCustomers}`
  : 'Customer records connected.';

const kbContext = knowledge.length > 0
  ? 'CLINICAL SOPs & PROTOCOLS:\n' + knowledge.map((c, i) => `[${i+1}] ${c.content || ''}`).join('\n\n')
  : 'Verified clinic standard operating procedures active.';

const system_prompt = `You are the Lead Practice Director & AI Business Coach for Dr. Chloe Vance, Medical Director of Aura Clinic (luxury medical aesthetics).

${customerContext}

${kbContext}

COACHING FRAMEWORK & INSTRUCTIONS:
1. Provide deep, data-grounded analysis. Always cite actual patient names, procedure values ($), inactivity days, and SOP document codes (e.g. SOP-RET-001).
2. Format every response with clean, professional structure:
   - ### Root-Cause Practice Analysis
   - ### Action Plan / Retention Protocol
   - > Blockquote containing ready-to-send SMS or Email Outreach Script for staff.
3. Address consultation conversion, high-value churn, and treatment package drop-offs with specific pricing and financing recommendations.
4. Keep tone decisive, clinical, and executive.`;

return [{ json: { message, session_id, topic, system_prompt } }];

const ds = $json;
const prev = $('Build AI Prompt').first().json;
const ai_response = ds?.choices?.[0]?.message?.content || 'Sorry, I could not generate a response.';
return [{ json: { ai_response, session_id: prev.session_id, user_message: prev.message, topic: prev.topic } }];
